"""PyTorch port of the authors' Keras/Theano network (repo/net/net.py).

Released architecture for one hidden layer of 50 units:

    Dropout(p)(inputs, training=True)            # dropout BEFORE every weight layer
    Dense(50, activation='relu', W_regularizer=l2(reg))
    Dropout(p)(inter, training=True)
    Dense(1, W_regularizer=l2(reg))

with reg = lengthscale**2 * (1 - dropout) / (2 * N * tau)   (net.py line 72, eq. 7),
loss = mean squared error on the standardized target, optimiser = Adam.

Because the released Keras layers are created with ``training=True``, dropout is
active at train AND predict time - a stochastic forward pass is the primitive of the
whole pipeline (this is what makes MC dropout possible).  We mirror that exactly:
``forward`` always applies dropout; ``forward_deterministic`` is only used for the
sanity baseline.
"""
import torch
import torch.nn as nn
import torch.nn.functional as F


class DropoutNet(nn.Module):

    def __init__(self, n_in: int, n_hidden, dropout: float):
        super().__init__()
        dims = [n_in] + [int(h) for h in n_hidden] + [1]
        self.layers = nn.ModuleList(
            [nn.Linear(dims[i], dims[i + 1]) for i in range(len(dims) - 1)]
        )
        self.dropout = float(dropout)
        self.reset_parameters()

    def reset_parameters(self):
        """Keras Dense defaults: glorot_uniform kernel, zero bias."""
        for lin in self.layers:
            nn.init.xavier_uniform_(lin.weight)
            nn.init.zeros_(lin.bias)

    def n_params(self) -> int:
        return sum(p.numel() for p in self.parameters())

    def l2_penalty(self):
        """Keras l2 applies to the kernel weights only (W_regularizer), not biases."""
        return sum((lin.weight ** 2).sum() for lin in self.layers)

    def forward(self, x):
        """Dropout BEFORE every weight layer, always active (Keras training=True)."""
        h = x
        last = len(self.layers) - 1
        for i, lin in enumerate(self.layers):
            h = F.dropout(h, p=self.dropout, training=True)
            h = lin(h)
            if i < last:
                h = torch.relu(h)
        return h.squeeze(-1)

    def forward_deterministic(self, x):
        """No dropout: plain MLP forward (sanity baseline only, not used for results)."""
        h = x
        last = len(self.layers) - 1
        for i, lin in enumerate(self.layers):
            h = lin(h)
            if i < last:
                h = torch.relu(h)
        return h.squeeze(-1)

